export function setupLocalVoice(audio){const $=id=>document.getElementById(id);let runtime;const message=text=>$('local-voice-status').textContent=text;
$('local-voice-prepare').onclick=async()=>{const file=$('local-voice-file').files[0];if(!file){message('Selecione a gravação autorizada da voz primeiro.');return}if(file.size>30*1024*1024){message('Use um arquivo de áudio de até 30 MB.');return}$('local-voice-prepare').disabled=true;$('local-voice-file').disabled=true;try{audio.clear();audio.setLocalVoice(null);await runtime?.dispose();runtime=null;message('Carregando motor gratuito neste aparelho…');const {prepareLocalVoice}=await import('/voice-runtime/local-voice.js');runtime=await prepareLocalVoice(file,p=>message('Baixando modelo: '+Math.round(p.loaded/1048576)+' MB'+(p.total?' / '+Math.round(p.total/1048576)+' MB':'')));audio.setLocalVoice(async(text,signal)=>{const start=performance.now();message('Gerando voz gratuita neste aparelho…');try{const blob=await runtime.say(text,signal);message('Voz gratuita pronta · última geração: '+((performance.now()-start)/1000).toFixed(1)+' s.');return blob}catch(error){message('Falha na voz gratuita: '+error.message);throw error}});$('local-voice-test').disabled=false;$('local-voice-release').disabled=false;message('Voz gratuita pronta · '+(runtime.backend.startsWith('webgpu')?'aceleração gráfica':'processador')+'. Ative o som para ouvir.')}catch(error){message('Não foi possível preparar a voz: '+error.message)}finally{$('local-voice-prepare').disabled=false;$('local-voice-file').disabled=false}};
$('local-voice-test').onclick=()=>{audio.say('Oi, João! Seja bem-vindo!');message('Teste na fila de áudio. Ative o som se ainda estiver desligado.')};
$('local-voice-release').onclick=async()=>{audio.clear();audio.setLocalVoice(null);await runtime?.dispose();runtime=null;$('local-voice-test').disabled=true;$('local-voice-release').disabled=true;message('Voz local encerrada. Selecione outra voz no painel de som.')};
}
